package com.gymmind.workout.application;
import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.member.domain.repository.MemberRepository; import com.gymmind.shared.error.*; import com.gymmind.shared.security.*; import com.gymmind.workout.domain.model.*; import com.gymmind.workout.infrastructure.persistence.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.*;
@Service public class DefaultTrainingPlanService implements TrainingPlanService {
 private final SpringDataWorkoutPlanTemplateRepository templates; private final SpringDataWorkoutPlanTemplateItemRepository items; private final SpringDataMemberWorkoutPlanRepository memberPlans; private final SpringDataMemberWorkoutScheduleRepository schedules; private final MemberRepository members;
 public DefaultTrainingPlanService(SpringDataWorkoutPlanTemplateRepository t,SpringDataWorkoutPlanTemplateItemRepository i,SpringDataMemberWorkoutPlanRepository p,SpringDataMemberWorkoutScheduleRepository s,MemberRepository m){templates=t;items=i;memberPlans=p;schedules=s;members=m;}
 private Long tenant(CurrentActor a){Long t=ActorAccess.tenantId(a);if(t==null)throw new BusinessException(ErrorCode.TENANT_CONTEXT_REQUIRED);return t;} private Long member(CurrentActor a){Long t=tenant(a);return members.findByTenantIdAndUserId(t,a.userId()).map(x->x.getId()).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));} private void manage(CurrentActor a){if(!(a.roles().contains(RoleCode.COACH)||a.roles().contains(RoleCode.GYM_ADMIN)))throw new BusinessException(ErrorCode.FORBIDDEN);}
 @Transactional(readOnly=true) public List<?> templates(CurrentActor a){Long t=tenant(a); if(a.roles().contains(RoleCode.MEMBER))return templates.findAllByTenantIdAndStatus(t,WorkoutPlanTemplateStatus.PUBLISHED); return templates.findAllByTenantIdAndStatus(t,WorkoutPlanTemplateStatus.PUBLISHED);}
 @Transactional(readOnly=true) public Object template(CurrentActor a,Long id){WorkoutPlanTemplate p=templates.findByTenantIdAndId(tenant(a),id).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND)); var detail=new LinkedHashMap<String,Object>(); detail.put("id",p.getId()); detail.put("name",p.getName()); detail.put("category",p.getCategory()); detail.put("goal",p.getGoal()); detail.put("description",p.getDescription()); detail.put("coachId",p.getCoachId()); detail.put("versionNumber",p.getVersionNumber()); detail.put("status",p.getStatus()); detail.put("items",items.findAllByTemplateIdOrderBySortOrder(p.getId()).stream().map(i->{var item=new LinkedHashMap<String,Object>(); item.put("id",i.getId()); item.put("exerciseId",i.getExerciseId()); item.put("phase",i.getPhase()); item.put("sortOrder",i.getSortOrder()); item.put("sets",i.getSets()); item.put("reps",i.getReps()); item.put("restSeconds",i.getRestSeconds()); item.put("weight",i.getWeight()); item.put("notes",i.getNotes()); return item;}).toList()); return detail;}
 @Transactional public Object create(CurrentActor a,CreateTemplateCommand c){manage(a);Long t=tenant(a);WorkoutPlanTemplate p=templates.save(new WorkoutPlanTemplate(t,a.userId(),c.name(),c.category(),c.goal(),c.description()));if(c.items()!=null)for(var x:c.items())items.save(new WorkoutPlanTemplateItem(p,x.exerciseId(),x.phase(),x.sortOrder(),x.sets(),x.reps(),x.restSeconds(),x.weight(),x.notes()));return p;}
 @Transactional public Object publish(CurrentActor a,Long id){manage(a);WorkoutPlanTemplate p=templates.findByTenantIdAndId(tenant(a),id).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));p.publish();return p;}
 @Transactional public Object select(CurrentActor a,Long id){Long t=tenant(a);Long m=member(a);WorkoutPlanTemplate p=templates.findByTenantIdAndId(t,id).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));if(p.getStatus()!=WorkoutPlanTemplateStatus.PUBLISHED)throw new BusinessException(ErrorCode.FORBIDDEN);return memberPlans.save(new MemberWorkoutPlan(t,m,p.getId(),p.getName(),p.getVersionNumber()));}
 @Transactional(readOnly=true) public List<?> memberPlans(CurrentActor a){return memberPlans.findAllByTenantIdAndMemberId(tenant(a),member(a));}
 @Transactional public Object schedule(CurrentActor a,Long planId,LocalDate date){Long t=tenant(a);Long m=member(a);memberPlans.findByTenantIdAndId(t,planId).filter(p->p.getMemberId().equals(m)).orElseThrow(()->new BusinessException(ErrorCode.FORBIDDEN));return schedules.save(new MemberWorkoutSchedule(t,planId,m,date));}
 @Transactional(readOnly=true) public List<?> calendar(CurrentActor a,LocalDate from,LocalDate to){return schedules.findAllByTenantIdAndMemberIdAndScheduledDateBetween(tenant(a),member(a),from,to);}
 @Transactional public void deleteSchedule(CurrentActor a,Long id){MemberWorkoutSchedule s=schedules.findByTenantIdAndId(tenant(a),id).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));if(!s.getMemberId().equals(member(a)))throw new BusinessException(ErrorCode.FORBIDDEN);schedules.delete(s);}
}
